ALTER TABLE ISTANZEEVENTI MODIFY IDEVENTO NUMERIC(10);
ALTER TABLE ISTANZEEVENTI ADD SOFTWARE VARCHAR(2);
ALTER TABLE ISTANZEEVENTI ADD CONSTRAINT FK_IEVENTI_SOFTWARE FOREIGN KEY (SOFTWARE) REFERENCES SOFTWARE(CODICE);
CREATE INDEX IDX_ISTEVENTI_001 ON ISTANZEEVENTI (IDCOMUNE, SOFTWARE, FLAG_LETTO);
CREATE INDEX IDX_ISTEVENTI_002 ON ISTANZEEVENTI (IDCOMUNE, FKIDCATEGORIAEVENTO, SOFTWARE, FLAG_LETTO);
CREATE INDEX IDX_ISTEVENTI_003 ON ISTANZEEVENTI (IDCOMUNE, CODICEISTANZA,FLAG_LETTO);
